Now let's add covariates. Very briefly, in each version of the story presented, the protagonist does or does not take action (`action`), does or does not intend to harm as a means to their ends (`intention`), and does or does not make physical contact with whomever they're harming (`contact`).


::: {.cell layout-align="center"}

```{.r .cell-code}
regression_direct <- cmdstan_model(
  "stan_programs/regression_direct.stan", 
  stanc_options = list("O1")
  )
regression_direct$print()
```

::: {.cell-output .cell-output-stdout}

```
data {
  int<lower=1> N;             // Number of observations
  array[N] int<lower=0, upper=1> action; 
  array[N] int<lower=0, upper=1> intention;
  array[N] int<lower=0, upper=1> contact;
  int<lower=1> K;             // Number of ordinal categories
  array[N] int<lower=1, upper=K> y; // Observed ordinals
}

parameters {
  // Effects
  real bA; // Effect of action without intention
  real bC; // Effect of contact without intention
  real bI; // Effect of intention without action or contact
  real bIA; // Interaction of intention and action
  real bIC; // Interaction of intention and contact
  simplex[K] p; // Ordinal probabilities for situation with no action, no contact, and no intention
}

transformed parameters {
  vector[K-1] q;    // The cumulative probabilities
  ordered[K-1] c; // (Internal) cut points

  // Compute the cumulative probabilities
  q[1] = p[1];
  for (k in 2:(K-1)) {
    q[k] = q[k-1] + p[k];
  }

  // Compute cutpoints
  c = logit(q);
}

model {
  // Prior model
  bA ~ normal(0, 1);
  bC ~ normal(0, 1);
  bI ~ normal(0, 1);
  bIA ~ normal(0, 1);
  bIC ~ normal(0, 1);
  p ~ dirichlet(rep_vector(1, K)); 

  // Observational model
  vector[N] gamma; // Latent affinities
  for (i in 1:N) {
    gamma[i] = bA*action[i] + bC*contact[i] + intention[i]*(bI + bIA*action[i] + bIC*contact[i]); 
  }
  y ~ ordered_logistic(gamma, c);
}
```


:::
:::


::: {.cell layout-align="center"}

```{.r .cell-code}
stan_data <- compose_data(
  select(df, action, contact, intention),
  y = df$response,
  K = 7,
  N = length(y)
)
if (file.exists("fit_objects/m_direct_regress.Rds")) {
  m_direct_regress <- readRDS("fit_objects/m_direct_regress.Rds")
} else {
  m_direct_regress <- regression_direct$sample(
    data = stan_data,
    chains = 4,
    iter_warmup = 500,
    iter_sampling = 500
)
  m_direct_regress$save_object(file = "fit_objects/m_direct_regress.Rds")
}
```
